set-header.value:
@{
          var tenantId    = "{{tenant-id}}";
          var clientId    = "{{apim-app-client-id}}";
          var gatewayUrl  = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
          var redirectUri = Uri.EscapeDataString(gatewayUrl + "/callback");
          var state       = System.Guid.NewGuid().ToString("N");
          return
            "https://login.microsoftonline.com/" + tenantId + "/v2.0/adminconsent"
            + "?client_id="     + clientId
            + "&redirect_uri="  + redirectUri
            + "&scope="         + Uri.EscapeDataString("https://management.azure.com/.default")
            + "&state="         + state;
        }
